class ConditionalRevealMines(MineBehavior):
    """
    When a non-mine cell is revealed, if it has zero adjacent mines,
    all its unrevealed, unflagged neighbors are also revealed.
    This can lead to large cascades of safe cells, rewarding players
    who can identify and clear areas of 'zero' quickly.
    """

    def on_post_action(self, board, game, action):
        if action.get("hit_mine"):
            return

        for r, c in action.get("newly_revealed", []):
            cell = board.grid[r][c]
            if not cell.is_mine and cell.adjacent_mines == 0:
                queue: deque[tuple[int, int]] = deque([(r, c)])
                seen: set[tuple[int, int]] = {(r, c)}

                while queue:
                    cr, cc = queue.popleft()
                    for nr, nc in board.neighbors(cr, cc):
                        if (nr, nc) in seen:
                            continue

                        neighbor_cell = board.grid[nr][nc]
                        if not (neighbor_cell.is_revealed or neighbor_cell.is_flagged or neighbor_cell.is_mine):
                            seen.add((nr, nc))
                            # We are not calling game.reveal, but marking as revealed directly.
                            # The game will re-check state after this method returns.
                            board.grid[nr][nc].is_revealed = True
                            action["newly_revealed"].append((nr, nc))
                            queue.append((nr, nc))

class RecedingMines(MineBehavior):
    """
    When a mine is revealed, it and its immediate unrevealed neighbors are removed
    from the board (turned into safe cells). This makes mines a temporary obstacle
    rather than a permanent threat, encouraging aggressive exploration once mines 
    are discovered.
    """

    def on_post_action(self, board, game, action):
        if action["action"] == "reveal" and action["hit_mine"]:
            r, c = action["coords"]
            mines_to_clear = [(r, c)]
            for nr, nc in board.neighbors(r, c):
                cell = board.grid[nr][nc]
                if cell.is_mine and not cell.is_revealed and not cell.is_flagged:
                    mines_to_clear.append((nr, nc))

            for mr, mc in mines_to_clear:
                if board.grid[mr][mc].is_mine:
                    board.grid[mr][mc].is_mine = False
                    board.grid[mr][mc].is_revealed = True
                    board.grid[mr][mc].adjacent_mines = 0
                    action["newly_revealed"].append((mr, mc))

            board.recompute_adjacency()

class EdgeMineCountInfo(InfoStrategy):
    """
    Shows the mine count only for cells on the border of the grid.
    Other cells display nothing, forcing the player to deduce mine
    locations based on perimeter information.
    """

    def encode(self, board: "Board", r: int, c: int) -> str:
        if r == 0 or r == board.config.rows - 1 or c == 0 or c == board.config.cols - 1:
            n = board.grid[r][c].adjacent_mines
            return str(n) if n > 0 else ""
        else:
            return ""

class ConditionalDetonatingMines(MineBehavior):
    """
    If the player reveals a number that is equal to the count of its
    unrevealed and unflagged neighbors, all of those neighbors detonate.
    This creates a strategic layer where players must identify 'perfect'
    number cells to trigger safe reveals.
    """

    def on_post_action(self, board, game, action):
        if action['action'] == 'flag':
            return

        for r, c in action['newly_revealed']:
            cell = board.grid[r][c]
            if cell.is_mine or cell.adjacent_mines > 0:
                # Only consider revealed safe cells with adjacent mine counts
                continue

            unrevealed_neighbors = []
            for nr, nc in board.neighbors(r, c):
                neighbor_cell = board.grid[nr][nc]
                if not neighbor_cell.is_revealed and not neighbor_cell.is_flagged:
                    unrevealed_neighbors.append((nr, nc))

            if len(unrevealed_neighbors) == cell.adjacent_mines and cell.adjacent_mines > 0:
                # This is a 'perfect' number cell situation
                for nr, nc in unrevealed_neighbors:
                    neighbor = board.grid[nr][nc]
                    if neighbor.is_mine:
                        board.reveal_mine(nr, nc)
                        action['newly_revealed'].append((nr, nc))
                        game.player.take_damage()
                        if not game.player.is_alive():
                            return

class ExplodingNeighborReveal(RevealStrategy):
    """
    When a cell with adjacent mines is revealed, all its unrevealed neighbors are revealed.
    If any of these newly revealed neighbors are mines, they detonate.
    """

    def reveal(self, board: Board, r: int, c: int) -> list[tuple[int, int]]:
        cell = board.grid[r][c]
        if cell.is_revealed or cell.is_flagged:
            return []

        if cell.is_mine:
            board.reveal_mine(r, c)
            # Framework handles player damage for mine detonation
            return [(r, c)]

        cell.is_revealed = True
        revealed_cells = [(r, c)]

        if cell.adjacent_mines > 0:
            for nr, nc in board.neighbors(r, c):
                neighbor_cell = board.grid[nr][nc]
                if not neighbor_cell.is_revealed and not neighbor_cell.is_flagged:
                    if neighbor_cell.is_mine:
                        board.reveal_mine(nr, nc)
                        # Framework handles player damage for mine detonation
                        revealed_cells.append((nr, nc))
                    else:
                        neighbor_cell.is_revealed = True
                        revealed_cells.append((nr, nc))
        return revealed_cells

class DiagonalMooreNeighborhood(Neighborhood):
    """Moore neighborhood with only diagonal neighbors. Information is sparser than Moore, but adjacency is preserved, creating interesting deduction puzzles."""

    _OFFSETS = [(-1, -1), (-1, 1), (1, -1), (1, 1)]

    def offsets(self) -> list[tuple[int, int]]:
        return self._OFFSETS

class NeighborProximityInfo(InfoStrategy):
    """
    Revealed cells show the number of *unrevealed neighbors* that are mines.
    This shifts focus from total adjacent mines to the immediate threat of
    unconfirmed mines, making deduction more localized and tactical.
    """

    def encode(self, board: "Board", r: int, c: int) -> str:
        unrevealed_mine_neighbors = 0
        for nr, nc in board.neighbors(r, c):
            if board.in_bounds(nr, nc):
                neighbor_cell = board.grid[nr][nc]
                if not neighbor_cell.is_revealed and not neighbor_cell.is_flagged and neighbor_cell.is_mine:
                    unrevealed_mine_neighbors += 1

        return str(unrevealed_mine_neighbors) if unrevealed_mine_neighbors > 0 else ""

class ProactiveMines(MineBehavior):
    """
    When a numbered cell is revealed, any unrevealed neighboring mines that are
    fully constrained (e.g., a '1' next to only one unrevealed cell) are immediately
    revealed. This encourages more aggressive deduction by removing ambiguity
    and revealing threats proactively.
    """

    def on_post_action(self, board, game, action):
        if action["action"] == "flag":
            return

        newly_revealed_cells = action["newly_revealed"]
        newly_checked: set[tuple[int, int]] = set()

        for r, c in newly_revealed_cells:
            cell = board.grid[r][c]
            if cell.is_mine or cell.adjacent_mines == 0 or (r, c) in newly_checked:
                continue

            # Check neighbors for fully constrained mines
            for nr, nc in board.neighbors(r, c):
                neighbor_cell = board.grid[nr][nc]
                if neighbor_cell.is_mine and not neighbor_cell.is_revealed and not neighbor_cell.is_flagged:
                    # Count unrevealed, unflagged neighbors of this potential mine
                    constrained = True
                    potential_mine_neighbors = []
                    for nnr, nnc in board.neighbors(nr, nc):
                        potential_mine_neighbors.append((nnr, nnc))

                    # Check if the number of adj mines for (r,c) matches the number of unrevealed neighbors of (nr, nc)
                    if cell.adjacent_mines > 0:
                        unrevealed_neighbor_count = 0
                        for p_nr, p_nc in potential_mine_neighbors:
                            p_cell = board.grid[p_nr][p_nc]
                            if not p_cell.is_revealed and not p_cell.is_flagged:
                                unrevealed_neighbor_count += 1
                        if cell.adjacent_mines == unrevealed_neighbor_count:
                            # This neighbor IS a mine, reveal it
                            board.reveal_mine(nr, nc)
                            action["newly_revealed"].append((nr, nc))
                            newly_checked.add((nr, nc))
                            # If revealing a mine, player takes damage
                            game.player.take_damage()
                            if not game.player.is_alive():
                                return

class DeducingMines(MineBehavior):
    """
    When a numbered cell is revealed, if the number of that cell is equal
    to the number of its unrevealed neighbors, then all of those unrevealed
    neighbors must be mines. This behavior automatically flags them.
    This creates opportunities for immediate, guaranteed deductions.
    """

    def on_post_action(self, board, game, action):
        if action["action"] == "flag":
            return

        newly_revealed_coords = action["newly_revealed"]
        cells_to_check = set()

        # Add cells that were just revealed to our check list
        for r, c in newly_revealed_coords:
            cells_to_check.add((r, c))

        # Also add neighbors of newly revealed cells, as they might now become deducible
        # (though the primary trigger is the newly revealed numbered cell itself)
        for r, c in newly_revealed_coords:
            for nr, nc in board.neighbors(r, c):
                if board.in_bounds(nr, nc):
                    cells_to_check.add((nr, nc))

        flags_to_set = []

        for r, c in cells_to_check:
            if not board.in_bounds(r, c) or board.grid[r][c].is_revealed or board.grid[r][c].is_flagged:
                continue

            cell = board.grid[r][c]
            if cell.adjacent_mines == 0 or cell.adjacent_mines is None: # Skip '0' cells or cells without computed adjacency
                continue

            unrevealed_neighbors = []
            for nr, nc in board.neighbors(r, c):
                if board.in_bounds(nr, nc):
                    neighbor_cell = board.grid[nr][nc]
                    if not neighbor_cell.is_revealed and not neighbor_cell.is_flagged:
                        unrevealed_neighbors.append((nr, nc))

            if len(unrevealed_neighbors) == cell.adjacent_mines:
                # All unrevealed neighbors must be mines, so flag them.
                # We collect these to flag them all at once to avoid modifying the board
                # while iterating over it, which could cause issues with neighbor calculations.
                for nr, nc in unrevealed_neighbors:
                    if not board.grid[nr][nc].is_flagged and board.grid[nr][nc].is_mine: # Double check it's a mine and not already flagged
                        flags_to_set.append((nr, nc))

        # Now apply the flags
        for r, c in flags_to_set:
            if not board.grid[r][c].is_flagged:
                board.grid[r][c].is_flagged = True
                # We don't add to action["newly_revealed"] because these are flags, not reveals
                # The game's win/loss check will handle the implications of these flags.

class ProactiveNeighborReveal(RevealStrategy):
    """
    When a numbered cell is revealed, if all of its unrevealed neighbors are mines,
    it detonates them and reveals them. This encourages proactive deduction.
    """

    def reveal(self, board: Board, r: int, c: int) -> list[tuple[int, int]]:
        cell = board.grid[r][c]
        revealed_cells = []

        if cell.is_mine:
            # This should ideally not happen due to safe_first_click or game logic,
            # but for robustness, we treat it as a normal reveal.
            cell.is_revealed = True
            revealed_cells.append((r, c))
            return revealed_cells

        cell.is_revealed = True
        revealed_cells.append((r, c))

        if cell.adjacent_mines > 0:
            unrevealed_neighbors = []
            for nr, nc in board.neighbors(r, c):
                neighbor_cell = board.grid[nr][nc]
                if not neighbor_cell.is_revealed and not neighbor_cell.is_flagged:
                    unrevealed_neighbors.append((nr, nc))

            mine_neighbor_count = 0
            for nr, nc in unrevealed_neighbors:
                if board.grid[nr][nc].is_mine:
                    mine_neighbor_count += 1

            if mine_neighbor_count == cell.adjacent_mines:
                # All unrevealed neighbors are mines, detonate them.
                for nr, nc in unrevealed_neighbors:
                    # Check if the neighbor is still unrevealed and not flagged, as it might have been revealed/flagged by another process.
                    if not board.grid[nr][nc].is_revealed and not board.grid[nr][nc].is_flagged:
                        if board.grid[nr][nc].is_mine:
                            board.reveal_mine(nr, nc)
                            revealed_cells.append((nr, nc))
                        else:
                            # This case should not happen if cell.adjacent_mines is accurate
                            # but as a safety, we reveal it if it's not a mine.
                            board.grid[nr][nc].is_revealed = True
                            revealed_cells.append((nr, nc))

        # Standard cascade for '0' cells
        if cell.adjacent_mines == 0 and not (r, c) in revealed_cells:  # Ensure we don't re-process if it was just detonated
            queue = deque([(r, c)])
            visited = {(r, c)}

            while queue:
                cr, cc = queue.popleft()
                curr = board.grid[cr][cc]
                if curr.is_revealed or curr.is_flagged or curr.is_mine:
                    continue
                curr.is_revealed = True
                if (cr, cc) not in revealed_cells: # Avoid adding duplicates if already detonated
                    revealed_cells.append((cr, cc))

                if curr.adjacent_mines == 0:
                    for nr, nc in board.neighbors(cr, cc):
                        if (nr, nc) not in visited:
                            visited.add((nr, nc))
                            queue.append((nr, nc))

        return revealed_cells

class ConditionalCascadeWin(WinCondition):
    """
    Wins when a cell with N adjacent mines is revealed, and exactly N
    of its unrevealed neighbors are mines. This encourages agents to not only
    reveal safe cells but also to precisely identify mine clusters.
    """

    def evaluate(self, board, game, action):
        newly_revealed = action.get('newly_revealed', [])
        if not newly_revealed:
            return None

        for r, c in newly_revealed:
            cell = board.grid[r][c]
            if not cell.is_revealed or cell.is_mine:
                continue

            adjacent_mines = cell.adjacent_mines
            if adjacent_mines == 0:
                continue

            unrevealed_neighbors_count = 0
            mine_neighbors_count = 0

            for nr, nc in board.neighbors(r, c):
                neighbor_cell = board.grid[nr][nc]
                if not neighbor_cell.is_revealed:
                    unrevealed_neighbors_count += 1
                    if neighbor_cell.is_mine:
                        mine_neighbors_count += 1

            if unrevealed_neighbors_count > 0 and mine_neighbors_count == adjacent_mines:
                return "won"

        return None

class HexagonalNeighborhood(Neighborhood):
    """Hexagonal grid connectivity. Each cell has up to 6 neighbors."""

    _OFFSETS = [
        (-1, 0), (1, 0),  # Up, Down
        (0, -1), (0, 1),  # Left, Right
        (-1, 1), (1, -1)  # Diagonals (depending on orientation)
    ]

    def offsets(self) -> list[tuple[int, int]]:
        return self._OFFSETS

class UnstableMines(MineBehavior):
    """
    When a mine is revealed, it destabilizes and can cause nearby unrevealed
    mines to also reveal themselves and detonate. The chance of detonation
    increases with the number of adjacent revealed mines to the detonating
    mine. This encourages careful play around already revealed numbers.
    """

    def on_post_action(self, board, game, action):
        if not action.get("hit_mine"):
            return

        origin = action["coords"]
        queue: deque[tuple[int, int]] = deque([origin])
        seen: set[tuple[int, int]] = {origin}

        while queue:
            r, c = queue.popleft()

            # Check direct neighbors of the detonated mine for instability
            candidates = []
            for nr, nc in board.neighbors(r, c):
                if board.grid[nr][nc].is_mine and not board.grid[nr][nc].is_revealed:
                    candidates.append((nr, nc))

            for nr, nc in candidates:
                if (nr, nc) in seen:
                    continue

                # Calculate instability based on revealed neighbors
                revealed_neighbors_count = 0
                for nnr, nnc in board.neighbors(nr, nc):
                    if board.grid[nnr][nnc].is_revealed:
                        revealed_neighbors_count += 1

                # Probability of detonation increases with revealed neighbors
                # A simple linear relationship, can be tuned.
                detonation_chance = min(1.0, revealed_neighbors_count * 0.2) # Max 20% with 5 revealed neighbors

                if self._rng.random() < detonation_chance:
                    seen.add((nr, nc))
                    board.reveal_mine(nr, nc)
                    action["newly_revealed"].append((nr, nc))
                    game.player.take_damage()
                    if not game.player.is_alive():
                        return
                    # Add to queue for cascading effect
                    queue.append((nr, nc))

class ProactiveCascade(RevealStrategy):
    """
    Reveals a cell and proactively attempts to reveal its neighbors if the revealed cell's
    adjacent mine count is met by its unrevealed neighbors. This encourages immediate deduction
    based on local information.
    """

    def reveal(self, board: Board, r: int, c: int) -> list[tuple[int, int]]:
        cell = board.grid[r][c]
        if cell.is_revealed or cell.is_flagged:
            return []

        cell.is_revealed = True
        revealed_cells = [(r, c)]

        if cell.adjacent_mines == 0:
            # Standard cascade for zero cells
            queue: deque[tuple[int, int]] = deque([(r, c)])
            visited: set[tuple[int, int]] = {(r, c)}

            while queue:
                cr, cc = queue.popleft()
                current_cell = board.grid[cr][cc]

                if current_cell.is_revealed or current_cell.is_flagged or current_cell.is_mine:
                    continue

                current_cell.is_revealed = True
                revealed_cells.append((cr, cc))

                if current_cell.adjacent_mines == 0:
                    for nr, nc in board.neighbors(cr, cc):
                        if (nr, nc) not in visited:
                            visited.add((nr, nc))
                            queue.append((nr, nc))
        else:
            # Proactive neighbor reveal for numbered cells
            unrevealed_neighbors = []
            for nr, nc in board.neighbors(r, c):
                neighbor_cell = board.grid[nr][nc]
                if not neighbor_cell.is_revealed and not neighbor_cell.is_flagged:
                    unrevealed_neighbors.append((nr, nc))

            if len(unrevealed_neighbors) == cell.adjacent_mines:
                for nr, nc in unrevealed_neighbors:
                    neighbor_cell = board.grid[nr][nc]
                    if not neighbor_cell.is_revealed and not neighbor_cell.is_flagged and not neighbor_cell.is_mine:
                        # Recursively call reveal, but only if it's not a mine and not already revealed/flagged
                        # This is different from the cascade, as it's a controlled chain reaction
                        # We don't want to trigger cascade from these proactively revealed cells unless they are 0
                        neighbor_cell.is_revealed = True
                        revealed_cells.append((nr, nc))
                        if neighbor_cell.adjacent_mines == 0:
                           # If a proactively revealed neighbor is a 0, then cascade from it
                           queue: deque[tuple[int, int]] = deque([(nr, nc)])
                           visited: set[tuple[int, int]] = {(nr, nc)}
                           while queue:
                                ccr, ccn = queue.popleft()
                                current_nn_cell = board.grid[ccr][ccn]
                                if current_nn_cell.is_revealed or current_nn_cell.is_flagged or current_nn_cell.is_mine:
                                    continue
                                current_nn_cell.is_revealed = True
                                revealed_cells.append((ccr, ccn))
                                if current_nn_cell.adjacent_mines == 0:
                                    for nnr, nnc in board.neighbors(ccr, ccn):
                                        if (nnr, nnc) not in visited:
                                            visited.add((nnr, nnc))
                                            queue.append((nnr, nnc))

        return revealed_cells

class ProximityDetonation(MineBehavior):
    """
    When a mine is revealed, it causes all adjacent unrevealed mines to detonate.
    This detonation can cascade, causing further detonations.
    This introduces a risk-reward for revealing cells near potential mine clusters.
    """

    def on_post_action(self, board, game, action):
        if not action.get("hit_mine"):
            return

        origin_mine = action["coords"]
        detonation_queue: deque[tuple[int, int]] = deque([origin_mine])
        triggered_mines: set[tuple[int, int]] = {origin_mine}

        while detonation_queue:
            current_r, current_c = detonation_queue.popleft()

            # Check neighbors of the detonating mine
            for nr, nc in board.neighbors(current_r, current_c):
                if not board.in_bounds(nr, nc):
                    continue

                neighbor_cell = board.grid[nr][nc]

                # If it's an unrevealed mine and we haven't processed it yet
                if neighbor_cell.is_mine and not neighbor_cell.is_revealed and (nr, nc) not in triggered_mines:
                    triggered_mines.add((nr, nc))
                    board.reveal_mine(nr, nc)
                    action["newly_revealed"].append((nr, nc))
                    game.player.take_damage()

                    if not game.player.is_alive():
                        return  # Player died, stop the chain reaction

                    # Add this newly detonated mine to the queue for cascading effects
                    detonation_queue.append((nr, nc))

class BinaryNeighborInfo(InfoStrategy):
    """
    Reveals only whether a cell has *any* adjacent mines (1) or *no* adjacent mines (0).
    This drastically reduces information, forcing players to rely on the exact count
    of neighbors revealed as '0's to deduce mine locations.
    """

    def __init__(self, seed: int | None = None) -> None:
        super().__init__(seed)

    def encode(self, board: "Board", r: int, c: int) -> str:
        n = board.grid[r][c].adjacent_mines
        if n == 0:
            return "0"
        return "1"

class MineAdjacentLoss(WinCondition):
    """
    The game is lost if any revealed cell has a mine as an adjacent cell.
    This forces players to be extremely careful with their reveals,
    as a single mistake can lead to an immediate loss.
    """

    def evaluate(self, board, game, action):
        for r, row in enumerate(board.grid):
            for c, cell in enumerate(row):
                if cell.is_revealed and not cell.is_mine:
                    for nr, nc in board.neighbors(r, c):
                        if board.grid[nr][nc].is_mine:
                            return "lost"
        return None

class MineProximityCascade(RevealStrategy):
    """
    Reveals cells based on proximity to mines. When a cell is revealed:
    1. If it's a mine, it detonates and reveals its neighbors.
    2. If it's a number, it reveals all adjacent unrevealed cells.
    3. If it's a zero, it cascades like standard Minesweeper, but also detonates adjacent mines.
    This strategy heavily punishes incorrect guesses and rewards understanding minefield topology.
    """

    def reveal(self, board: Board, r: int, c: int) -> list[tuple[int, int]]:
        cell = board.grid[r][c]
        revealed_cells: list[tuple[int, int]] = []

        if cell.is_mine:
            board.reveal_mine(r, c)
            revealed_cells.append((r, c))
            # Detonate and reveal neighbors
            for nr, nc in board.neighbors(r, c):
                if board.in_bounds(nr, nc):
                    neighbor_cell = board.grid[nr][nc]
                    if not neighbor_cell.is_revealed and not neighbor_cell.is_flagged:
                        if neighbor_cell.is_mine:
                            # Detonate adjacent mine
                            board.reveal_mine(nr, nc)
                            revealed_cells.append((nr, nc))
                        else:
                            # Reveal non-mine neighbor
                            neighbor_cell.is_revealed = True
                            revealed_cells.append((nr, nc))
            return revealed_cells

        if cell.adjacent_mines > 0:
            cell.is_revealed = True
            revealed_cells.append((r, c))
            # Reveal all adjacent unrevealed cells
            for nr, nc in board.neighbors(r, c):
                if board.in_bounds(nr, nc):
                    neighbor_cell = board.grid[nr][nc]
                    if not neighbor_cell.is_revealed and not neighbor_cell.is_flagged:
                        neighbor_cell.is_revealed = True
                        revealed_cells.append((nr, nc))
            return revealed_cells

        # Standard cascade for zero-cell, but with mine detonation
        queue: deque[tuple[int, int]] = deque([(r, c)])
        visited: set[tuple[int, int]] = {(r, c)}

        while queue:
            cr, cc = queue.popleft()
            curr = board.grid[cr][cc]
            if curr.is_revealed or curr.is_flagged or curr.is_mine:
                continue

            curr.is_revealed = True
            revealed_cells.append((cr, cc))

            if curr.adjacent_mines == 0:
                for nr, nc in board.neighbors(cr, cc):
                    if board.in_bounds(nr, nc):
                        neighbor_cell = board.grid[nr][nc]
                        if not neighbor_cell.is_revealed and not neighbor_cell.is_flagged:
                            if neighbor_cell.is_mine:
                                # Detonate adjacent mine
                                board.reveal_mine(nr, nc)
                                revealed_cells.append((nr, nc))
                            elif (nr, nc) not in visited:
                                visited.add((nr, nc))
                                queue.append((nr, nc))

        return revealed_cells

class DirectionalMineCountInfo(InfoStrategy):
    """
    Reveals a single digit representing the number of adjacent mines,
    but also provides a directional arrow indicating the general
    direction of the NEAREST mine. This combines local count deduction
    with global spatial awareness.
    """

    def encode(self, board: "Board", r: int, c: int) -> str:
        if not board.grid[r][c].is_revealed:
            return ""

        adjacent_mines = board.grid[r][c].adjacent_mines

        if adjacent_mines == 0:
            return ""

        # Find the closest mine and determine direction
        closest_mine_dist = float('inf')
        closest_mine_dir = ''

        for rr in range(board.config.rows):
            for cc in range(board.config.cols):
                if board.grid[rr][cc].is_mine:
                    dist = max(abs(rr - r), abs(cc - c))  # Chebyshev distance
                    if dist < closest_mine_dist:
                        closest_mine_dist = dist
                        # Determine direction
                        dr = rr - r
                        dc = cc - c
                        dirs = []
                        if dr > 0: dirs.append('↓')
                        if dr < 0: dirs.append('↑')
                        if dc > 0: dirs.append('→')
                        if dc < 0: dirs.append('←')
                        closest_mine_dir = ''.join(sorted(dirs))

        # Combine mine count and direction
        if closest_mine_dir:
            return f"{adjacent_mines}{closest_mine_dir}"
        else:
            return str(adjacent_mines)

class CascadingMineDetonationWin(WinCondition):
    """
    Wins when a mine detonation triggers a cascade that reveals all mines.
    This condition heavily rewards understanding mine adjacency and potential
    chain reactions, making strategic mine placement and careful reveals crucial.
    """

    def evaluate(self, board, game, action):
        if action["hit_mine"]:
            # Check if a mine detonation caused a cascade that revealed all mines.
            # The simplest way to check this is to see if all mines are now revealed.
            all_mines_revealed = True
            for r in range(board.config.rows):
                for c in range(board.config.cols):
                    if board.grid[r][c].is_mine and not board.grid[r][c].is_revealed:
                        all_mines_revealed = False
                        break
                if not all_mines_revealed:
                    break

            if all_mines_revealed:
                return "won"

        return None

class ProactiveMineDetonator(RevealStrategy):
    """When a cell with N adjacent mines is revealed, and exactly N of its unrevealed neighbors are mines, cause those neighbors to detonate."""

    def reveal(self, board: Board, r: int, c: int) -> list[tuple[int, int]]:
        cell = board.grid[r][c]
        revealed_cells = []

        if cell.is_revealed or cell.is_flagged:
            return revealed_cells

        cell.is_revealed = True
        revealed_cells.append((r, c))

        if cell.adjacent_mines > 0:
            unrevealed_neighbors = []
            for nr, nc in board.neighbors(r, c):
                neighbor_cell = board.grid[nr][nc]
                if not neighbor_cell.is_revealed and not neighbor_cell.is_flagged:
                    unrevealed_neighbors.append((nr, nc))

            if len(unrevealed_neighbors) == cell.adjacent_mines:
                # Check if all unrevealed neighbors are mines
                all_neighbors_are_mines = True
                for nr, nc in unrevealed_neighbors:
                    if not board.grid[nr][nc].is_mine:
                        all_neighbors_are_mines = False
                        break

                if all_neighbors_are_mines:
                    # Detonate these mines
                    for nr, nc in unrevealed_neighbors:
                        if board.grid[nr][nc].is_mine and not board.grid[nr][nc].is_revealed:
                            board.reveal_mine(nr, nc) # This will reveal the mine and detonate neighbors if applicable
                            revealed_cells.append((nr, nc))
        return revealed_cells

class ConditionalCascadeReveal(RevealStrategy):
    """
    Standard minesweeper cascade, but only for cells with a numbered value equal to 
    the count of their unrevealed neighbors. This rewards precise local deduction 
    and can quickly reveal large safe areas.
    """

    def reveal(self, board: Board, r: int, c: int) -> list[tuple[int, int]]:
        cell = board.grid[r][c]
        if cell.is_revealed or cell.is_flagged or cell.is_mine:
            return []

        # Count unrevealed neighbors
        unrevealed_neighbors_count = 0
        for nr, nc in board.neighbors(r, c):
            neighbor_cell = board.grid[nr][nc]
            if not neighbor_cell.is_revealed and not neighbor_cell.is_flagged:
                unrevealed_neighbors_count += 1

        # Only cascade if the cell's number matches its unrevealed neighbors
        if cell.adjacent_mines > 0 and cell.adjacent_mines != unrevealed_neighbors_count:
            cell.is_revealed = True
            return [(r, c)]

        # Proceed with standard cascade logic if the condition is met
        queue: deque[tuple[int, int]] = deque([(r, c)])
        visited: set[tuple[int, int]] = {(r, c)}
        revealed: list[tuple[int, int]] = []

        while queue:
            cr, cc = queue.popleft()
            curr = board.grid[cr][cc]
            if curr.is_revealed or curr.is_flagged or curr.is_mine:
                continue
            curr.is_revealed = True
            revealed.append((cr, cc))

            # Count unrevealed neighbors for the current cell
            current_unrevealed_neighbors_count = 0
            for nr, nc in board.neighbors(cr, cc):
                neighbor_cell = board.grid[nr][nc]
                if not neighbor_cell.is_revealed and not neighbor_cell.is_flagged:
                    current_unrevealed_neighbors_count += 1

            # Cascade only if the condition is met for the current cell, or if it's a zero
            if curr.adjacent_mines == 0 or (curr.adjacent_mines > 0 and curr.adjacent_mines == current_unrevealed_neighbors_count):
                for nr, nc in board.neighbors(cr, cc):
                    if (nr, nc) not in visited:
                        visited.add((nr, nc))
                        queue.append((nr, nc))
        return revealed

class HexagonalNeighborhood(Neighborhood):
    """Hexagonal grid connectivity. Increases neighbor count and local information density, potentially making deductions easier or harder based on mine placement."""

    _OFFSETS = [
        (-1, 0), (-1, 1),  # Top-left, Top-right
        ( 0, -1), ( 0, 1),  # Middle-left, Middle-right
        ( 1, 0), ( 1, -1)   # Bottom-left, Bottom-right
    ]

    def offsets(self) -> list[tuple[int, int]]:
        return self._OFFSETS
